def rtm_coverage(requirements, links):
    reqs = set(requirements)
    covered = {r for r, t in links if r in reqs}
    pct = round(len(covered) / len(reqs) * 100, 1) if reqs else 0.0
    return {
        "coverage_pct": pct,
        "untested": sorted(reqs - covered),
        "orphans": sorted({t for r, t in links if r not in reqs}),
    }
